-- =====================================================================
-- Mapa Ciudadano CDE · Datos de ejemplo para la presentación (145 denuncias, 10 obras)
-- Pegá este archivo en Supabase > SQL Editor y tocá "Run" DESPUÉS de 01-esquema.sql.
-- Las fechas se calculan desde el momento en que lo ejecutás. Para sacarlos: 03-borrar-ejemplos.sql
-- Archivo generado por scripts/generar-ejemplos.mjs
-- =====================================================================
begin;
delete from public.denuncias where demo;

-- Tiempo de resolución de ejemplo para las estadísticas.
update public.denuncias set resuelta_en = least(now(), creada + make_interval(days => 3 + votos % 9, hours => gravedad * 36))
 where demo and estado = 'resuelta';


-- Historial de ejemplo (queda encadenado como cualquier otro registro).
do $$ begin
  if not exists (select 1 from public.historial where demo) then
    perform public.registrar('Obra asignada a E-1015', 'Constructora Paraná S.A. · Gs. 2.624.000', true, now() - interval '20 days', 'Dirección de Obras Públicas');
    perform public.registrar('Obra asignada a E-1011', 'Vialtec del Este S.R.L. · Gs. 2.088.000', true, now() - interval '17 days', 'Dirección de Obras Públicas');
    perform public.registrar('Obra asignada a E-1023', 'Asfaltos Alto Paraná · Gs. 3.263.000', true, now() - interval '14 days', 'Dirección de Obras Públicas');
    perform public.registrar('Obra asignada a E-1052', 'Electro Sur Ingeniería · Gs. 5.297.000', true, now() - interval '11 days', 'Dirección de Obras Públicas');
    perform public.registrar('Obra asignada a E-1021', 'Constructora Paraná S.A. · Gs. 2.028.000', true, now() - interval '8 days', 'Dirección de Obras Públicas');
    perform public.registrar('Obra E-1023 modificada', 'Monto: Gs. 2.610.000 → Gs. 3.263.000', true, now() - interval '2 days', 'Dirección de Obras Públicas');
  end if;
end $$;
commit;
